function s(n: number) : string {
    let r : string = ""
    for (let i : number = 0; i < n; i++) {
        if (i < 3) {
            r = r + i
        } else if (i < 6) {
            r = i + r
        } else {
            r = r + i
        }
    }
    return r
}

